sql.where:
B.DEL_DT IS NULL

	AND B.EXPSR_YN = #{expsrYn}


	AND B.RCMDTN_YN = #{rcmdtnYn}


	AND B.RCMDTN_CLSF_CD = #{rcmdtnClsfCd}


	AND B.NEW_BOOK_YR = #{newBookYr}


	AND B.NEW_BOOK_MM = #{newBookMm}


	AND B.REG_YMD >= #{startRegYmd}


	AND B.REG_YMD <= #{endRegYmd}




			AND B.BOOK_MNG_NO LIKE CONCAT('%', #{searchKeyword}, '%')


			AND B.BOOK_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND B.AUT_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND B.PBLCO_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND B.CLNO LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (
				B.BOOK_MNG_NO LIKE CONCAT('%', #{searchKeyword}, '%')
				OR B.BOOK_NM LIKE CONCAT('%', #{searchKeyword}, '%')
				OR B.AUT_NM LIKE CONCAT('%', #{searchKeyword}, '%')
				OR B.PBLCO_NM LIKE CONCAT('%', #{searchKeyword}, '%')
				OR B.CLNO LIKE CONCAT('%', #{searchKeyword}, '%')
			)

mapper.select:
SELECT



ORDER BY B.REG_YMD DESC, B.BOOK_SN DESC
LIMIT #{offset}, #{limit}

SELECT


WHERE B.BOOK_SN = #{bookSn}
AND B.DEL_DT IS NULL
